  const SNS = 20;
  const seamFade = Array.from({ length: SNS }, (_, j) => {
    const [o, w] = seamFadeProfile((j + .5) / SNS);
    return mk("path", { class: "nf",
      style: `stroke:var(--ink);stroke-opacity:${o.toFixed(3)};stroke-width:${w.toFixed(3)}` }, gBody);
  });
  /* The seam's other end, at the snout: the same banded run the other way up - full ink
     a hand's width short of the point, then thinner and fainter until the pen lifts.
     One set of bands serves both flanks; each arm feeds them from its own side. */
  const TNS = 12;
